import { existsSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { LocalBodyModel } from "../src/local/bodyModel";

const BIN = new URL("../standalone/body-model.bin", import.meta.url);
const REF = JSON.parse(readFileSync(new URL("./fixtures/body-ref.json", import.meta.url), "utf8"));

// The binary is generated by server/scripts/export_body_bin.py (not committed).
describe.skipIf(!existsSync(BIN))("browser body model matches the server", () => {
  it("produces the same mesh as Python for a preset", () => {
    const buf = readFileSync(BIN);
    const model = new LocalBodyModel(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength));
    const t0 = performance.now();
    const m = model.build({ sex: 0, height_cm: 158, weight: 0.7, muscle: 0.5, breast: 0.85, glutes: 0.6 });
    const ms = performance.now() - t0;
    expect(m.positions.length / 3).toBe(REF.n);
    expect(m.indices.length / 3).toBe(REF.t);
    expect(Array.from(m.indices.slice(0, 3))).toEqual(REF.tri0);
    expect(Array.from(m.indices.slice(-3))).toEqual(REF.triLast);
    for (const [i, p] of Object.entries(REF.samples) as [string, number[]][]) {
      for (let c = 0; c < 3; c++) expect(Math.abs(m.positions[3 * Number(i) + c] - p[c])).toBeLessThan(2e-4);
    }
    for (let c = 0; c < 3; c++) expect(Math.abs(m.landmarks["l-elbow"][c] - REF.elbow[c])).toBeLessThan(2e-4);
    let vol = 0;
    const P = m.positions, T = m.indices;
    for (let t = 0; t < T.length; t += 3) {
      const a = 3 * T[t], b = 3 * T[t + 1], c = 3 * T[t + 2];
      vol += P[a] * (P[b + 1] * P[c + 2] - P[b + 2] * P[c + 1]) - P[a + 1] * (P[b] * P[c + 2] - P[b + 2] * P[c]) + P[a + 2] * (P[b] * P[c + 1] - P[b + 1] * P[c]);
    }
    expect(vol / 6).toBeCloseTo(REF.volume, 4);
    console.log("browser body build", Math.round(ms), "ms");
  });
});

describe.skipIf(!existsSync(BIN))("browser skin matches the server", () => {
  it("has the same strongest bones and weights", () => {
    const buf = readFileSync(BIN);
    const model = new LocalBodyModel(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength));
    const m = model.build({ sex: 0, height_cm: 158, weight: 0.7, muscle: 0.5, breast: 0.85, glutes: 0.6 });
    expect(m.skin).toBeDefined();
    expect(m.skin!.bones[8].name).toBe(REF.bone8.name);
    for (let c = 0; c < 3; c++) expect(Math.abs(m.skin!.bones[8].head[c] - REF.bone8.head[c])).toBeLessThan(2e-4);
    for (const [v, [idx, w]] of Object.entries(REF.skin) as [string, [number[], number[]]][]) {
      const i = Number(v);
      for (let k = 0; k < 4; k++) {
        if (w[k] < 3) continue; // ties among zero weights may order differently
        expect(m.skin!.index[4 * i + k]).toBe(idx[k]);
        expect(Math.abs(m.skin!.weight[4 * i + k] - w[k])).toBeLessThanOrEqual(2);
      }
    }
  });
});
